// ==========================================
// أكواد عرض المنتجات (بدون سيرفر محلي)
// ==========================================

// دالة رسم المنتجات من المصفوفة المحلية في حال وجود الكونتينر
window.loadStoreProducts = function () {
    const container = document.getElementById('products-container');

    // لو الكونتينر مش موجود (زي في صفحة السلة مثلاً)، اخرج من الدالة بصمت
    if (!container) return;

    container.innerHTML = '';

    // بنشيك لو مصفوفة productsDB مش موجودة أو فاضية
    if (typeof productsDB === 'undefined' || productsDB.length === 0) {
        container.innerHTML = '<p style="color: #94a3b8; text-align: center;">لا توجد منتجات مضافة حالياً.</p>';
        return;
    }

    // لفة على كل منتج في المصفوفة ورسمه
    productsDB.forEach(product => {
        // التحقق من حالة المخزون
        const inStock = product.inStock !== false;

        const actionButton = inStock
            ? `<button onclick="window.buyProduct('${product.name}', '${product.price}')" style="background: #06b6d4; color: #fff; border: none; padding: 10px; border-radius: 6px; font-weight: bold; cursor: pointer; width: 100%;">شراء الآن 🛒</button>`
            : `<button disabled style="background: #64748b; color: #fff; border: none; padding: 10px; border-radius: 6px; font-weight: bold; cursor: not-allowed; width: 100%;">نفذت الكمية (Out of Stock)</button>`;

        container.innerHTML += `
            <div style="background: #1e293b; border: 1px solid #38bdf8; border-radius: 10px; padding: 15px; text-align: center; color: #fff;">
                <img src="${product.img}" alt="${product.name}" onerror="this.src='../assets/images/favicon.png'" style="width: 100%; height: 180px; object-fit: cover; border-radius: 6px;">
                <h3 style="color: #38bdf8; margin: 10px 0 5px;">${product.name}</h3>
                <p style="color: #94a3b8; font-size: 13px;">القسم: ${product.category}</p>
                <p style="font-size: 14px; color: #cbd5e1; height: 40px; overflow: hidden;">${product.specs || ''}</p>
                <p style="color: #4ade80; font-weight: bold; font-size: 18px; margin: 10px 0;">${product.price} ج.م</p>
                ${actionButton}
            </div>
        `;
    });
};

// دالة الشراء المباشر والتحويل للواتساب (مفيش سيرفر هيفصل هنا)
window.buyProduct = function (productName, productPrice) {
    const customerName = prompt("أدخل اسمك الكريم:");
    if (!customerName) return;

    const phone = prompt("أدخل رقم هاتفك للتواصل:");
    if (!phone) return;

    const address = prompt("أدخل عنوان الاستلام بالتفصيل:");
    if (!address) return;

    // بنحول العميل للواتساب فوراً
    alert('جاري تحويلك للواتساب لإتمام الطلب... 🚀');
    const myWhatsAppNumber = "201017229055";
    const message = `السلام عليكم، أريد طلب هذا المنتج:%0A` +
        `- المنتج: ${productName}%0A` +
        `- السعر: ${productPrice} ج.م%0A` +
        `- الاسم: ${customerName}%0A` +
        `- الهاتف: ${phone}%0A` +
        `- العنوان: ${address}`;

    window.open(`https://wa.me/${myWhatsAppNumber}?text=${message}`, '_blank');
};

// تشغيل الدالة أوتوماتيك أول ما الصفحة تفتح (بأمان تام)
document.addEventListener('DOMContentLoaded', () => {
    window.loadStoreProducts();
});
